INSERT INTO feature VALUES('shared-endpoints','sessions','Shared endpoints: acquire, release and dup',NULL,'planned','ordinary',NULL,'`acquire` takes the linear end of a shared endpoint, `release` gives the shared end back, and `dup` copies a shared endpoint. The grammar reads the three forms, and the checker does not reach them.',NULL,'corpus/ledger/syntax/acquire-expression.gandr corpus/ledger/syntax/release-expression.gandr corpus/ledger/syntax/dup-expression.gandr',NULL,'#1501');
